using System;
using System.Linq;
using DocumentFormat.OpenXml.Presentation;

namespace OfficeIMO.PowerPoint {
    public partial class PowerPointSlide {
        /// <summary>
        ///     Appends a shape generated by the layout system, assigning a fresh id and a unique name based on the
        ///     generated one, and returns its tracked wrapper.
        /// </summary>
        internal PowerPointShape AppendLayoutShape(Shape shape, bool textBox) {
            if (shape == null) throw new ArgumentNullException(nameof(shape));
            NonVisualDrawingProperties? properties = shape.NonVisualShapeProperties?.NonVisualDrawingProperties;
            if (properties != null) {
                properties.Id = AllocateShapeId();
                string baseName = string.IsNullOrWhiteSpace(properties.Name?.Value) ? "Shape" : properties.Name!.Value!;
                // A name that already carries its index ("Screenshot Annotation 2") is kept when it is unique.
                bool indexed = baseName.Length > 0 && char.IsDigit(baseName[baseName.Length - 1]);
                properties.Name = indexed && !ShapeList.Any(s => s.Name == baseName) ? baseName : GenerateUniqueName(baseName);
            }

            CommonSlideData data = SlideRoot.CommonSlideData ??= new CommonSlideData(new ShapeTree());
            ShapeTree tree = data.ShapeTree ??= new ShapeTree();
            tree.AppendChild(shape);
            return textBox
                ? TrackShape(new PowerPointTextBox(shape, _slidePart))
                : TrackShape(new PowerPointAutoShape(shape));
        }

        /// <summary>Name of the slide layout this slide uses, or null.</summary>
        internal string? SlideLayoutName => _slidePart.SlideLayoutPart?.SlideLayout?.CommonSlideData?.Name?.Value;
    }
}
